import numpy as np, cv2
s=np.load('source_pixels.npz')['rgb']
def flow(a,b):
 return cv2.calcOpticalFlowFarneback(cv2.cvtColor(a,cv2.COLOR_RGB2GRAY),cv2.cvtColor(b,cv2.COLOR_RGB2GRAY),None,.5,4,21,5,7,1.5,0)
def warp(f,fl,t):
 h,w=f.shape[:2];gx,gy=np.meshgrid(np.arange(w,dtype=np.float32),np.arange(h,dtype=np.float32))
 return cv2.remap(f,gx+t*fl[...,0],gy+t*fl[...,1],cv2.INTER_LINEAR,borderMode=cv2.BORDER_REPLICATE)
for i in range(0,22):
 fl=flow(s[i],s[i+1]);a=.5
 fw=warp(s[i],fl,a).astype(float);bw=warp(s[i+1],-fl,1-a).astype(float)
 diff=np.abs(fw-bw).mean(2)
 print(i,'mean',round(diff.mean(),2),'p99',round(np.percentile(diff,99),1),'max',round(diff.max(),1),'moving',round(diff[55:135,45:205].mean(),2))
PY"
